//! F_004: independently seeded v1 SQLite Golden and version/fail-closed regression.
//! The SQL seed is not generated by the production Native Writer.
use boardsi_model::{BoardKind, BoardModel};
use boardsi_native::{load, save};
use rusqlite::Connection;
use sha2::{Digest, Sha256};
use std::fs;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};

static NEXT: AtomicU64 = AtomicU64::new(0);

fn temporary(case: &str) -> PathBuf {
    let dir = std::env::temp_dir();
    dir.join(format!(
        "boardsi-f004-{}-{}-{}.bsi",
        case,
        std::process::id(),
        NEXT.fetch_add(1, Ordering::Relaxed)
    ))
}

fn independent_golden(case: &str) -> PathBuf {
    let file = temporary(case);
    let conn = Connection::open(&file).expect("create independent SQLite");
    conn.execute_batch(include_str!("../../../schemas/bsi/v1.sql"))
        .expect("published v1 DDL");
    conn.execute_batch(include_str!("../../../schemas/bsi/golden-v1-empty.sql"))
        .expect("independent semantic seed");
    drop(conn);
    file
}

fn mutate(file: &PathBuf, sql: &str) {
    let conn = Connection::open(file).expect("open a mutation copy");
    conn.execute_batch(sql)
        .expect("apply syntactically valid mutation");
}

fn assert_rejected_unchanged(file: &PathBuf, expected_code: &str) {
    let before = fs::read(file).expect("read input");
    let err = load(file).err().expect("fail closed");
    assert_eq!(err.code(), expected_code);
    assert_eq!(fs::read(file).unwrap(), before, "reader modified source");
    // Save must not overwrite a file that cannot be fully read and preserved.
    assert!(save(file, &BoardModel::empty(BoardKind::Pcb)).is_err());
    assert_eq!(fs::read(file).unwrap(), before, "writer modified source");
}

#[test]
fn frozen_binary_v1_golden_sha_and_reader_are_cross_platform() {
    let bytes = include_bytes!("../../../schemas/bsi/golden-v1-empty.bsi");
    let expected_sha = include_str!("../../../schemas/bsi/golden-v1-empty.sha256").trim();
    let actual_sha = format!("{:x}", Sha256::digest(bytes));
    assert_eq!(actual_sha, expected_sha, "frozen binary bytes changed");
    let file = temporary("frozen-binary");
    fs::write(&file, bytes).unwrap();
    let model = load(&file).expect("read immutable cross-OS v1 SQLite");
    assert!(!model.is_read_only());
    assert_eq!(model.model(), &BoardModel::empty(BoardKind::Pcb));
    fs::remove_file(file).unwrap();
}

#[test]
fn frozen_nine_geometry_golden_is_exactly_pinned_and_loadable() {
    let bytes = include_bytes!("../../../schemas/bsi/golden-v1-nine-geometry.bsi");
    let expected_sha =
        include_str!("../../../schemas/bsi/golden-v1-nine-geometry.sha256").trim();
    assert_eq!(format!("{:x}", Sha256::digest(bytes)), expected_sha);
    let path = temporary("nine-geometry");
    fs::write(&path, bytes).unwrap();
    let loaded = load(&path).expect("decode historical rich geometry Golden");
    assert!(!loaded.is_read_only());
    let board = loaded.model();
    assert_eq!(board.traces.len(), 1);
    assert_eq!(board.arcs.len(), 1);
    assert_eq!(board.areas.len(), 1);
    assert_eq!(board.areas[0].cutouts.len(), 1);
    assert_eq!(board.padstacks.len(), 1);
    assert_eq!(board.pads.len(), 1);
    assert_eq!(board.vias.len(), 1);
    assert_eq!(board.drills.len(), 1);
    assert_eq!(board.outlines.len(), 1);
    assert_eq!(board.outlines[0].cutouts.len(), 1);
    assert_eq!(board.stackup.layers.len(), 2);
    assert_eq!(board.components.len(), 1);
    assert_eq!(board.pins.len(), 1);
    fs::remove_file(path).unwrap();
}

#[test]
fn independent_v1_golden_is_readable_without_writer() {
    let p = independent_golden("baseline");
    let file = fs::read(&p).unwrap();
    assert_eq!(&file[..16], b"SQLite format 3\0");
    let board = load(&p).expect("v1 independent historical reader");
    assert!(!board.is_read_only());
    assert_eq!(board.model(), &BoardModel::empty(BoardKind::Pcb));
    let conn = Connection::open(&p).unwrap();
    let id: String = conn
        .query_row("SELECT file_uuid FROM file_meta", [], |row| row.get(0))
        .unwrap();
    assert_eq!(id, "00000000-0000-4000-8000-000000000004");
    drop(conn);
    fs::remove_file(p).unwrap();
}

#[test]
fn v1_minor_future_is_read_only_and_source_bytes_survive() {
    let p = independent_golden("minor");
    mutate(&p, "UPDATE file_meta SET format_minor=7 WHERE singleton=1;");
    let before = fs::read(&p).unwrap();
    let board = load(&p).expect("inspect future optional-only minor");
    assert!(board.is_read_only());
    assert_eq!(
        board.save_as(temporary("minor-save")).err().unwrap().code(),
        "BSI_UNSUPPORTED_REQUIRED"
    );
    assert_eq!(fs::read(&p).unwrap(), before);
    fs::remove_file(p).unwrap();
}

#[test]
fn optional_payload_is_not_silently_lost() {
    let p = independent_golden("optional");
    mutate(
        &p,
        "INSERT INTO extensions(extension_name,extension_version,required,payload) \
         VALUES('independent-future-vendor',1,0,X'00FFCAFE');",
    );
    let before = fs::read(&p).unwrap();
    let loaded = load(&p).expect("optional extension inspection");
    assert!(loaded.is_read_only());
    assert_eq!(
        loaded
            .save_as(temporary("optional-output"))
            .err()
            .unwrap()
            .code(),
        "BSI_UNSUPPORTED_REQUIRED"
    );
    assert_eq!(fs::read(&p).unwrap(), before);
    fs::remove_file(p).unwrap();
}

#[test]
fn required_and_future_ddl_are_independently_rejected() {
    let p = independent_golden("required");
    mutate(
        &p,
        "INSERT INTO features(name,feature_version,required,opaque_payload) \
         VALUES('future-copper',1,1,X'01');",
    );
    assert_rejected_unchanged(&p, "BSI_UNSUPPORTED_REQUIRED");
    fs::remove_file(&p).unwrap();

    let p = independent_golden("future-ddl");
    mutate(&p, "PRAGMA user_version=2;");
    assert_rejected_unchanged(&p, "BSI_FUTURE_SCHEMA");
    fs::remove_file(&p).unwrap();

    let p = independent_golden("minimum-reader");
    mutate(
        &p,
        "UPDATE file_meta SET format_minor=1,min_reader_minor=1 WHERE singleton=1;",
    );
    assert_rejected_unchanged(&p, "BSI_UNSUPPORTED_REQUIRED");
    fs::remove_file(&p).unwrap();
}

#[test]
fn unversioned_schema_addition_is_not_mistaken_for_optional_extension() {
    let p = independent_golden("schema-extension");
    mutate(
        &p,
        "CREATE TABLE unversioned_future_payload(x INTEGER NOT NULL) STRICT;",
    );
    assert_rejected_unchanged(&p, "BSI_INVALID");
    fs::remove_file(p).unwrap();
}

#[test]
fn no_published_pre_v1_migration_is_fabricated() {
    let p = independent_golden("unpublished");
    mutate(&p, "PRAGMA user_version=0;");
    assert_rejected_unchanged(&p, "BSI_INVALID");
    fs::remove_file(p).unwrap();
}
